import type { McpIcon, McpPreset } from './mcp.ts';

/**
 * Bundled marks for the first-party MCP presets, as inline PNG data URLs.
 *
 * Haus Server stamps these onto a preset connection whose discovery resolved no
 * icon, and the App draws them on Recommended presets before one is added. The
 * presets are Haus-curated, so the mark is Haus's to ship; a server-advertised
 * icon or site favicon still wins once one resolves.
 *
 * Sources: CoinGecko from docs.coingecko.com’s published android-chrome-192x192.png
 * favicon; MerchBase from the MerchBase dashboard logo (128px), RankWrangler
 * from its extension `icon-128.png`, Google Calendar from Google's published
 * calendar favicon (`ssl.gstatic.com/calendar/images/dynamiclogo_2020q4/
 * calendar_31_2x.png`), GitHub from the Invertocat in Primer Octicons
 * (`icons/mark-github-24.svg`) rasterized to 128px, black for light and white
 * for dark, X from its published logo mark drawn white on a black 128px tile
 * (one variant serves both themes). Skool uses its published favicon resized to 128px. Regenerate with `base64 -i <file>.png`.
 */
export const mcpPresetIcons: Record<McpPreset, McpIcon> = {
    skool: {
        dark: null,
        light: 'data:image/png;base64,',
    },
    coingecko: {
        dark: null,
        light: 'data:image/png;base64,',
    },
    github: {
        dark: 'data:image/png;base64,',
        light: 'data:image/png;base64,',
    },
    'google-calendar': {
        dark: null,
        light: 'data:image/png;base64,',
    },
    merchbase: {
        dark: null,
        light: 'data:image/png;base64,',
    },
    rankwrangler: {
        dark: null,
        light: 'data:image/png;base64,',
    },
    x: {
        dark: null,
        light: 'data:image/png;base64,',
    },
};
